class Builder:
    def __init__(self):
        self.lines=[f'out{i} = out{i}' for i in range(32)]; self.n=32
        self.c0=self.new('0'); self.c1=self.new('1')
    def new(self,e): i=self.n; self.lines.append(f'out{i} = {e}'); self.n+=1; return i
    def op(self,x,s,y): return self.new(f'out{x} {s} out{y}')
    def inv(self,x): return self.new(f'~out{x}')
    def xor(self,x,y): return self.op(x,'^',y)
    def and_(self,x,y): return self.op(x,'&',y)
    def or_(self,x,y): return self.op(x,'|',y)
    def fa(self,x,y,c):
        t=self.xor(x,y); s=self.xor(t,c); co=self.or_(self.and_(x,y),self.and_(t,c)); return s,co
    def add(self,a,b,w):
        r=[]; c=self.c0
        for i in range(w): s,c=self.fa(a[i],b[i],c); r.append(s)
        return r
    def sub(self,a,b,w):
        r=[]; br=self.c0
        for i in range(w):
            t=self.xor(a[i],b[i]); d=self.xor(t,br)
            br=self.or_(self.and_(self.inv(a[i]),b[i]),self.and_(self.inv(t),br)); r.append(d)
        return r,br
    def mux(self,x,y,s):
        ns=self.inv(s); return self.or_(self.and_(x,ns),self.and_(y,s))
    def muxv(self,x,y,s): return [self.mux(a,b,s) for a,b in zip(x,y)]
    def mul(self,a,b,w):
        # Karatsuba multiplication, truncated to w bits.
        if w==1: return [self.and_(a[0],b[0])]
        m=w//2
        a0,a1=a[:m],a[m:]; b0,b1=b[:m],b[m:]
        z0=self.mul(a0,b0,m*2 if False else m)
        z2=self.mul(a1,b1,m)
        # products are truncated m bits where only low result bits are needed;
        # cross term needs m+1 bits, so use padded operands and width m+1.
        ap=self.add(a0,a1,m); bp=self.add(b0,b1,m)
        z1=self.mul(ap,bp,m+1)
        z1=self.sub(z1+[self.c0], z0+[self.c0], m+1)[0]
        z1=self.sub(z1, z2+[self.c0], m+1)[0]
        r=[self.c0]*w
        for i,x in enumerate(z0):
            if i<w: r[i]=self.xor(r[i],x)
        for i,x in enumerate(z1):
            if i+m<w: r[i+m]=self.xor(r[i+m],x)
        for i,x in enumerate(z2):
            if i+2*m<w: r[i+2*m]=self.xor(r[i+2*m],x)
        return r

def main():
    b=Builder(); inp=list(range(32))
    # Restoring integer square root, processing input bit-pairs MSB first.
    W=34; rem=[b.c0]*W; root=[b.c0]*17
    for i in range(15,-1,-1):
        shifted=[b.c0,b.c0]+rem[:W-2]
        shifted[0]=inp[2*i]; shifted[1]=inp[2*i+1]
        trial=[b.c0]*W
        # trial = (root << 2) + 1
        trial[0]=b.c1
        for j in range(17): trial[j+2]=root[j]
        diff,borrow=b.sub(shifted,trial,W); ge=b.inv(borrow)
        rem=b.muxv(shifted,diff,ge)
        nr=[b.c0]*17
        for j in range(16): nr[j]=root[j+1]
        nr[16]=b.c0
        nr[0]=b.mux(b.c0,b.c1,ge)
        # root <<= 1, then set low bit if accepted
        root=b.muxv([b.c0]*17,nr, b.c1) if False else nr
        root[0]=b.mux(b.c0,b.c1,ge)
    # Fast doubling Fibonacci, 16-bit root scan.
    a=[b.c0]*32; bb=[b.c1]+[b.c0]*31
    for k in range(15,-1,-1):
        two=[b.c0]+bb[:31]
        t=b.sub(two,a,32)[0]
        c=b.mul(a,t,32)
        aa=b.mul(a,a,32); sq=b.mul(bb,bb,32); d=b.add(aa,sq,32)
        a2=b.muxv(c,d,root[k]); b2=b.muxv(d,b.add(c,d,32),root[k]); a,bb=a2,b2
    for bit in a: b.new(f'out{bit}')
    assert b.n<32000,b.n
    with open('/app/gates.txt','w') as f:f.write('\n'.join(b.lines)+'\n')
    print(b.n)
if __name__=='__main__':main()

